class SmartDevice {
  constructor(id, name) {
    this.id = id;
    this.name = name;
    this._isOn = false;
  }

  turnOn() {
    this._isOn = true;
    return `${this.name} is now ON.`
  }

  turnOff() {
    this._isOn = false;
    return `${this.name} is now OFF.`
  }

  getStatus() {
    return `${this.name} (ID: ${this.id}) is currently ${this._isOn ? 'ON' : 'OFF'}.`;
  }

  operate(command) {
    throw new Error("Operate method must be implemented by subclasses.");
  }
}

class SmartLight extends SmartDevice {
  constructor(id, name, maxBrightness) {
    super(id, name);
    this.maxBrightness = maxBrightness;
    this._brightness = 0;
  }

  operate(brightnessLevel) {
    if (brightnessLevel < 0 || brightnessLevel > this.maxBrightness) {
      return `Error: Brightness level must be between 0 and ${this.maxBrightness}. Received ${brightnessLevel}.`;
    }
    this._brightness = brightnessLevel;
    this.turnOn(); // Ensure light is on when operated
    return `${this.name} brightness set to ${this._brightness}%.`;
  }
}

class SmartThermostat extends SmartDevice {
  constructor(id, name, minTemp, maxTemp) {
    super(id, name);
    this.minTemp = minTemp;
    this.maxTemp = maxTemp;
    this._targetTemperature = minTemp;
  }

  operate(targetTemperature) {
    if (targetTemperature < this.minTemp || targetTemperature > this.maxTemp) {
      return `Error: Target temperature must be between ${this.minTemp}°C and ${this.maxTemp}°C. Received ${targetTemperature}°C.`;
    }
    this._targetTemperature = targetTemperature;
    this.turnOn(); // Ensure thermostat is on when operated
    return `${this.name} target temperature set to ${this._targetTemperature}°C.`;
  }
}

